#include <iostream>
#include <algorithm>

using namespace std;

using ll = long long;

const int Mod = 998244353;

int sum(int a, int b) {
    return (a + b >= Mod ? a + b - Mod : a + b);
}

int mul(int a, int b) {
    return static_cast<ll>(a) * b % Mod;
}

ll powm(ll a, ll b) {
    ll res = 1;
    while (b) {
        if (b & 1) {
            res = mul(res, a);
        }
        a = mul(a, a);
        b >>= 1;
    }
    return res;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n, m, l, r;
    cin >> n >> m >> l >> r;

    if (l == r) {
        cout << 1 << '\n';
        return 0;
    }

    if (n > m) {
        swap(n, m);
    }

    r = r - l + 1;

    if (min(n, m) == 1) {
        ll cnt = n * m;
        ll cntodd = r - r / 2;
        ll cnteven = r / 2;
        int ans = 0;

        if (cntodd) {
            ans = sum(ans, powm(cntodd, cnt));
        }
        if (cnteven) {
            ans = sum(ans, powm(cnteven, cnt));
        }

        cout << ans << '\n';
        return 0;
    }

    cout << powm(r, n * m) << '\n';
    return 0;
}

