#include <iostream>
#include <algorithm>

using namespace std;

using ll = long long;

const int Mod = 998244353;

int addmod(int a, int b) {
    int result = a + b;
    if (result >= Mod) result -= Mod;
    return result;
}

int mulmod(ll a, ll b) {
    return static_cast<int>((a % Mod) * (b % Mod) % Mod);
}

int powmod(ll a, ll b) {
    int result = 1;
    a %= Mod;

    while (b > 0) {
        if (b & 1) result = mulmod(result, a);
        a = mulmod(a, a);
        b >>= 1;
    }

    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n, m, l, r;
    cin >> n >> m >> l >> r;

    if (l == r) {
        cout << 1 << '\n';
        return 0;
    }

    if (n > m) swap(n, m);

    ll values = r - l + 1;
    ll cells = n * m;

    if (n == 1) {
        ll firstParity = values - values / 2;
        ll secondParity = values / 2;

        int answer = addmod(
            powmod(firstParity, cells),
            powmod(secondParity, cells)
        );

        cout << answer << '\n';
        return 0;
    }

    if (n % 2 == 0 && m % 2 == 0) {
        int answer = powmod(values, cells);
        if (values & 1) answer = addmod(answer, 1);
        answer = mulmod(answer, (Mod + 1) / 2);

        cout << answer << '\n';
        return 0;
    }

    cout << powmod(values, cells) << '\n';
    return 0;
}

